package com.mfg.qms.controller;
import com.mfg.security.scope.ScopedQueryService;
import com.mfg.security.scope.ScopedResource;
import com.mfg.common.api.*;import com.mfg.common.exception.BizException;import com.mfg.qms.entity.Inspection;import com.mfg.qms.repo.InspectionRepository;import com.mfg.qms.service.QmsLifecycleService;import com.mfg.security.config.CurrentUser;import lombok.RequiredArgsConstructor;import org.springframework.data.domain.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.math.*;import java.time.*;
@RestController @RequestMapping("/api/qms/inspections") @RequiredArgsConstructor public class InspectionController{private final ScopedQueryService scope;private final InspectionRepository repo;private final QmsLifecycleService flow;@GetMapping @PreAuthorize("hasAuthority('QMS:INSPECTION:VIEW')")public ApiResponse<Page<Inspection>>page(@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int size){return ApiResponse.ok(scope.page(ScopedResource.INSPECTION,Inspection.class,page,size,null,null));}@GetMapping("/{id}")@PreAuthorize("hasAuthority('QMS:INSPECTION:VIEW')")public ApiResponse<Inspection>detail(@PathVariable Long id){scope.requireVisible(ScopedResource.INSPECTION,id);return ApiResponse.ok(repo.findById(id).orElseThrow(()->BizException.notFound("检验单",id)));}@PostMapping @PreAuthorize("hasAuthority('QMS:INSPECTION:CREATE')")public ApiResponse<Inspection>create(@RequestBody Inspection i){if(repo.existsByInspectionNo(i.getInspectionNo()))throw BizException.of(ErrorCode.MASTER_DATA_ALREADY_EXISTS,"检验单号已存在");i.setResult("PENDING");i.setInspectDate(LocalDate.now());i.setInspectorCode(CurrentUser.usernameOrSystem());return ApiResponse.ok(repo.save(i));}@PostMapping("/{id}/judge")@PreAuthorize("hasAuthority('QMS:INSPECTION:JUDGE')")public ApiResponse<?>judge(@PathVariable Long id,@RequestParam BigDecimal qualifiedQty,@RequestParam BigDecimal defectQty,@RequestParam String result){scope.requireVisible(ScopedResource.INSPECTION,id);return ApiResponse.ok(flow.judge(id,qualifiedQty,defectQty,result));}}
